return {
  guard: {
    hook: "onEvent",
    eventType: "guard",
    async promptOnPlayer(H, actor) {
      const allies = H.actors.hunters().filter(hunter => (hunter.id !== actor.id) && !H.condition.has(hunter, "dead"));
      const targetId = await H.ask.one({
        title: "Sacred",
        label: "Choose a Hunter to restore 1 Resolve",
        options: allies.map(hunter => ({ value: hunter.id, label: hunter.name })),
      });
      if (!targetId) return false;
      const target = allies.find(hunter => hunter.id === targetId);
      await H.resource.adjust(target, { resolve: 1 });
      await H.chat.post(`${target.name} restores 1 Resolve (Sacred).`, actor);
      return true;
    },
  },
};
